1	import { NextResponse, type NextRequest } from "next/server";
2	import { updateSession } from "@/integrations/supabase/middleware";
3	
4	// Next.js 16 renamed the `middleware` convention to `proxy`. The exported
5	// function name should now be `proxy` (though `middleware` still works
6	// with a deprecation warning). See:
7	// https://nextjs.org/docs/messages/middleware-to-proxy
8	
9	// Routes that require an authenticated user. Unauthenticated visitors
10	// are redirected to /auth.
11	const PROTECTED_PREFIXES = [
12	  "/",
13	  "/jobs",
14	  "/profile",
15	  "/billing",
16	  "/settings",
17	  "/team",
18	  "/tasks",
19	  "/activity",
20	  "/career-settings",
21	  "/integrations",
22	  "/reports",
23	  "/agency",
24	  "/talent-pool",
25	  "/sequences",
26	] as const;
27	
28	// Admin-only routes. Non-admin visitors are redirected to /.
29	// Admin role verification happens in the page's own layout via
30	// requireAdmin() since middleware can't query user_roles without a
31	// round-trip that would slow every request.
32	const ADMIN_PREFIXES = ["/admin"] as const;
33	
34	function isProtectedPath(pathname: string): boolean {
35	  return PROTECTED_PREFIXES.some(
36	    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
37	  );
38	}
39	
40	function isAdminPath(pathname: string): boolean {
41	  return ADMIN_PREFIXES.some(
42	    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
43	  );
44	}
45	
46	export async function proxy(request: NextRequest) {
47	  const { supabaseResponse, user } = await updateSession(request);
48	
49	  const { pathname } = request.nextUrl;
50	
51	  // Block unauthenticated access to protected + admin routes
52	  if ((isProtectedPath(pathname) || isAdminPath(pathname)) && !user) {
53	    const redirectUrl = request.nextUrl.clone();
54	    redirectUrl.pathname = "/auth";
55	    // Only set ?next= for non-root paths — Auth.tsx defaults to "/" already
56	    if (pathname !== "/") {
57	      redirectUrl.searchParams.set("next", pathname);
58	    }
59	    const redirectResponse = NextResponse.redirect(redirectUrl);
60	    // Forward any refreshed auth cookies from updateSession onto the
61	    // redirect response so a just-expired session doesn't force a
62	    // full re-login on the next request.
63	    supabaseResponse.cookies.getAll().forEach((cookie) => {
64	      redirectResponse.cookies.set(cookie);
65	    });
66	    return redirectResponse;
67	  }
68	
69	  return supabaseResponse;
70	}
71	
72	export const config = {
73	  matcher: [
74	    /*
75	     * Match all request paths except:
76	     * - _next/static (static assets)
77	     * - _next/image (image optimization)
78	     * - favicon.ico
79	     * - images, fonts, and other public static files
80	     */
81	    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|woff|woff2|ttf|otf)$).*)",
82	  ],
83	};
