8	import AppHeader from "@/components/AppHeader";
9	import AuthDialog from "@/components/AuthDialog";
10	import JobSidebar from "@/components/JobSidebar";
11	import JobDetailView from "@/components/JobDetailView";
12	import JobsOverviewCard from "@/components/JobsOverviewCard";
13	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
14	import { Card, CardContent } from "@/components/ui/card";
