34	export interface Result {
35	  id: string;
36	  resume_id: string;
37	  overall_score: number;
38	  missing_skills: string[];
39	  summary: string | null;
40	  interview_questions: any;
41	  filename: string;
42	  file_path: string | null;
43	  candidate_name: string | null;
44	  candidate_email?: string | null;
45	  candidate_phone?: string | null;
46	  candidate_location?: string | null;
47	  // Dynamic scoring fields
48	  hard_fit?: boolean;
49	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
50	  confidence?: number;
51	  strengths_json?: string[];
52	  gaps_json?: string[];
53	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
54	  matched_must_haves?: string[];
55	  missing_must_haves?: string[];
56	  scoring_version?: string;
57	  pending?: boolean;
58	  parsed_json?: any;
59	  assigned_to?: string | null;
60	  source?: string | null;
61	}
