72	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
73	
74	const ONBOARDING_KEY = "rankora_onboarding_done";
75	
76	const Index = () => {
77	  const { user, profile } = useAuth();
78	  const searchParams = useSearchParams();
79	  const pathname = usePathname() ?? "/";
80	  const router = useRouter();
81	
82	  // Helper to clear all query params (replaces react-router setSearchParams({}, { replace: true }))
83	  const clearSearchParams = useCallback(() => {
84	    router.replace(pathname);
85	  }, [pathname, router]);
86	
87	  // Show onboarding wizard for first-time users
88	  const [showOnboarding, setShowOnboarding] = useState(() => {
89	    if (typeof window === "undefined") return false;
90	    return !localStorage.getItem(ONBOARDING_KEY);
91	  });
92	
93	  const completeOnboarding = useCallback(() => {
94	    localStorage.setItem(ONBOARDING_KEY, "1");
95	    setShowOnboarding(false);
96	  }, []);
97	
98	  const queryClient = useQueryClient();
99	
100	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
101	    queryKey: ["pastJobs", user?.id],
102	    queryFn: async () => {
103	      const { data: jobs } = await supabase
104	        .from("jobs")
105	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
106	        .eq("user_id", user!.id)
107	        .order("created_at", { ascending: false })
108	        .limit(50);
109	      if (!jobs) return [];
110	      return jobs.map((j: any) => ({
111	        id: j.id,
112	        title: j.title,
113	        job_description: j.job_description,
114	        status: j.status,
115	        created_at: j.created_at,
116	        resume_count: j.resumes?.[0]?.count ?? 0,
117	        jd_analysis_json: j.jd_analysis_json,
118	        dynamic_weights_json: j.dynamic_weights_json,
119	        inbox_email: j.inbox_email ?? null,
120	      })) as PastJob[];
121	    },
122	    enabled: !!user,
123	    staleTime: 2 * 60 * 1000,
124	  });
125	
126	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
127	  const [view, setView] = useState<ViewMode>(pathname === "/jobs" ? "my-jobs" : "dashboard");
128	  const [results, setResults] = useState<Result[]>([]);
129	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
130	  const [authOpen, setAuthOpen] = useState(false);
131	
132	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
133	
134	  // Sync view with route path
135	  useEffect(() => {
136	    if (pathname === "/jobs") {
137	      setView("my-jobs");
138	      setSelectedJobId(null);
139	    }
140	  }, [pathname]);
141	
142	  // Handle URL params for deep linking
143	  useEffect(() => {
144	    const jobParam = searchParams?.get("job") ?? null;
145	    const newParam = searchParams?.get("new") ?? null;
146	
147	    if (jobParam && user) {
148	      loadJobData(jobParam);
149	      clearSearchParams();
150	    } else if (newParam && user) {
151	      handleNewJob();
152	      clearSearchParams();
153	    }
154	    // eslint-disable-next-line react-hooks/exhaustive-deps
155	  }, [searchParams, user]);
156	
157	  const loadJobData = async (jobId: string) => {
158	    setSelectedJobId(jobId);
159	    setView("job-detail");
160	    try {
161	      // Single query for all resume data (was 2 separate queries)
162	      const { data: allResumes } = await supabase
163	        .from("resumes")
164	        .select("id, filename, file_path, candidate_name, created_at, parsed_json, source")
165	        .eq("job_id", jobId)
166	        .order("created_at", { ascending: false });
167	
168	      const resumeData = allResumes ?? [];
169	      setExistingResumes(resumeData.map((r) => ({
170	        id: r.id, filename: r.filename, file_path: r.file_path,
171	        candidate_name: r.candidate_name, created_at: r.created_at,
172	        source: (r as { source?: string | null }).source ?? null,
173	      })));
174	
175	      if (resumeData.length === 0) {
176	        setResults([]);
177	        return;
178	      }
179	
180	      const resumeIds = resumeData.map((r) => r.id);
181	      const { data: resultData } = await supabase
182	        .from("results")
183	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
184	        .in("resume_id", resumeIds);
185	
186	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
187	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
188	        const resume = resumeMap.get(r.resume_id);
189	        const parsed = resume?.parsed_json as any;
190	        return {
191	          ...r,
192	          overall_score: r.overall_score ?? 0,
193	          missing_skills: r.missing_skills ?? [],
194	          filename: resume?.filename ?? "Unknown",
195	          file_path: resume?.file_path ?? null,
196	          candidate_name: resume?.candidate_name ?? null,
197	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
198	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
199	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
200	          parsed_json: resume?.parsed_json ?? null,
201	          source: (resume as { source?: string | null })?.source ?? null,
202	        };
203	      });
204	      // Deduplicate by resume_id — keep highest scoring result per resume
205	      const deduped = new Map<string, Result>();
206	      for (const r of allMerged) {
207	        const existing = deduped.get(r.resume_id);
208	        if (!existing || r.overall_score > existing.overall_score) {
209	          deduped.set(r.resume_id, r);
210	        }
211	      }
212	      const merged = Array.from(deduped.values());
213	      merged.sort((a, b) => b.overall_score - a.overall_score);
214	      setResults(merged);
215	    } catch (err) {
216	      toast.error("Failed to load job data");
217	    }
218	  };
219	
220	  const handleNewJob = () => {
221	    setSelectedJobId(null);
222	    setView("new-job");
223	    setResults([]);
224	    setExistingResumes([]);
225	  };
226	
227	  const handleGoToDashboard = () => {
228	    setSelectedJobId(null);
229	    setView("dashboard");
230	    setResults([]);
231	    setExistingResumes([]);
232	    router.replace("/");
233	  };
234	
235	  const handleGoToMyJobs = () => {
236	    setSelectedJobId(null);
237	    setView("my-jobs");
238	    setResults([]);
239	    setExistingResumes([]);
240	    router.replace("/jobs");
241	  };
242	
243	  const handleJobCreated = (job: PastJob) => {
244	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
245	    setSelectedJobId(job.id);
246	    loadJobData(job.id);
247	  };
248	
249	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
250	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
251	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
252	    );
253	  };
254	
255	  const handleDeleteJobs = async (jobIds: string[]) => {
256	    try {
257	      const { error } = await supabase.from("jobs").delete().in("id", jobIds);
258	      if (error) throw error;
259	      queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
260	        (prev ?? []).filter((j) => !jobIds.includes(j.id))
261	      );
262	    } catch (err: any) {
263	      toast.error(err?.message || "Failed to delete jobs");
264	    }
265	  };
266	
267	  const requireAuth = useCallback(() => {
268	    if (!user) { setAuthOpen(true); return true; }
269	    return false;
270	  }, [user]);
271	
272	  return (
273	    <SidebarProvider className="h-svh overflow-hidden">
274	      <JobSidebar
275	        showDashboard={view === "dashboard"}
276	        showMyJobs={view === "my-jobs" || view === "job-detail"}
277	        onNewJob={handleNewJob}
278	        onDashboard={handleGoToDashboard}
279	        onMyJobs={handleGoToMyJobs}
280	        onAuthRequired={() => setAuthOpen(true)}
281	        isAuthenticated={!!user}
282	      />
283	
284	      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
285	        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
286	        <AppHeader />
287	        <div className="flex items-center h-10 px-4 md:hidden">
288	          <SidebarTrigger />
289	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
290	        </div>
291	        <div className="flex-1 overflow-y-auto">
292	
293	        {/* Dashboard view */}
294	        {view === "dashboard" && user ? (
