24	/**
25	 * Server-side guard for admin-only pages. Verifies both session AND
26	 * admin role via user_roles table.
27	 */
28	export async function requireAdmin() {
29	  const supabase = await createClient();
30	  const {
31	    data: { user },
32	  } = await supabase.auth.getUser();
33	
34	  if (!user) {
35	    redirect("/auth");
36	  }
37	
38	  const { data: roles } = await supabase
39	    .from("user_roles")
40	    .select("role")
41	    .eq("user_id", user.id);
42	
43	  const isAdmin = (roles ?? []).some(
44	    (r: { role: string }) => r.role === "admin",
45	  );
46	  if (!isAdmin) {
47	    redirect("/");
48	  }
49	
50	  return user;
51	}
